implementation:
#include <linux/pfkeyv2.h>
#include <linux/skbuff.h>
#include <linux/socket.h>
#include <linux/in.h>
#include <linux/ip.h>
#include <linux/errno.h>

int flush_key_notification_policy(const struct km_event *c) {
    struct sk_buff *skb;
    struct sadb_msg *hdr;
    int msg_size = sizeof(*hdr);

    skb = alloc_skb(msg_size, GFP_KERNEL);
    if (!skb) {
        return -ENOBUFS;
    }

    skb_put(skb, msg_size);
    skb_reset_transport_header(skb);
    hdr = skb_transport_header(skb);

    hdr->sadb_msg_version = PF_KEY_V2;
    hdr->sadb_msg_type = SADB_GETSPDINFO;
    hdr->sadb_msg_errno = 0;
    hdr->sadb_msg_satype = 0;
    hdr->sadb_msg_len = msg_size / sizeof(uint64_t);
    hdr->sadb_msg_reserved = 0;

    sock_broadcast(skb);

    return 0;
}
